import os
import torch


class Config:
    """
    Configuration for Supervised Bottleneck-Projected Dual-Stream Network (SB-PDS Net).
    Defines hyperparameters for data processing, model architecture, and training pipeline.
    """

    # -------------------------------------------------------------------------
    # Paths & Directories
    # -------------------------------------------------------------------------
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Metadata files generated by the previous step
    TRAIN_CSV = os.path.join(METADATA_DIR, "train.csv")
    VAL_CSV = os.path.join(METADATA_DIR, "val.csv")
    TEST_CSV = os.path.join(METADATA_DIR, "test.csv")

    # Original input files
    SAMPLE_SUBMISSION = os.path.join(INPUT_DIR, "sample_submission.csv")
    TRAIN_DICOM_DIR = os.path.join(INPUT_DIR, "train")
    TEST_DICOM_DIR = os.path.join(INPUT_DIR, "test")

    # Cache directory for deterministic data processing
    CACHE_DIR = "./working/idea_43/"
    os.makedirs(CACHE_DIR, exist_ok=True)

    # Submission output
    SUBMISSION_PATH = "./submission/submission.csv"
    os.makedirs(os.path.dirname(SUBMISSION_PATH), exist_ok=True)

    # -------------------------------------------------------------------------
    # Reproducibility
    # -------------------------------------------------------------------------
    SEED = 42

    # -------------------------------------------------------------------------
    # Data Preprocessing
    # -------------------------------------------------------------------------
    # Image parameters
    IMG_SIZE = 260  # Native resolution for EfficientNet-B2
    NUM_SLICES = 3  # Anchor slice + 2 boundary slices
    WINDOW_LEVEL = -600  # Lung window level (HU)
    WINDOW_WIDTH = 1500  # Lung window width (HU)

    # Tabular Feature Engineering
    # Note: 'Percent' is explicitly excluded to prevent proxy leakage.
    # 'Weeks' will be converted to relative time scaled by 0.01.
    TABULAR_FEATURES = ["Baseline_FVC", "Time_Scaled", "Age", "Sex", "SmokingStatus"]

    # Normalization constants (to be computed or used as fixed priors if needed)
    TIME_SCALE_FACTOR = 0.01

    # -------------------------------------------------------------------------
    # Model Architecture (SB-PDS Net)
    # -------------------------------------------------------------------------
    BACKBONE_NAME = "efficientnet_b2"
    PRETRAINED = True

    # Dimensions
    BACKBONE_OUT_DIM = 1408  # EfficientNet-B2 final feature map channels
    BOTTLENECK_DIM = 64  # Projection dimension for image features
    HIDDEN_DIM = 128  # MLP hidden dimension
    OUTPUT_DIM = 2  # Mean (FVC) and Std (Confidence)

    # Regularization
    DROPOUT_RATE = 0.0  # Disabled (Cite solution_lesson_node_00126)

    # Initialization
    # Standard initialization used (Cite solution_lesson_node_00118)

    # -------------------------------------------------------------------------
    # Training Hyperparameters
    # -------------------------------------------------------------------------
    EPOCHS = 30
    BATCH_SIZE = 32
    NUM_WORKERS = 4

    # Optimization
    OPTIMIZER = "AdamW"
    LR_BACKBONE = 1e-4  # Lower LR for pretrained backbone
    LR_HEAD = 1e-3  # Higher LR for MLP heads
    WEIGHT_DECAY = 1e-2

    # Scheduler
    SCHEDULER = "CosineAnnealingLR"
    T_MAX = EPOCHS  # Dynamic horizon linked to total epochs

    # Loss Function
    # Total Loss = L_metric(Final) + AUX_LOSS_WEIGHT * L_metric(Base)
    AUX_LOSS_WEIGHT = 0.5

    # Device
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    # -------------------------------------------------------------------------
    # Metric & Evaluation
    # -------------------------------------------------------------------------
    # Constants for Laplace Log Likelihood
    MIN_CONFIDENCE = 70.0  # Sigma clipped at 70 ml
    MAX_ERROR = 1000.0  # Error thresholded at 1000 ml
    SQRT_2 = 1.41421356

    # -------------------------------------------------------------------------
    # Debugging & Development
    # -------------------------------------------------------------------------
    # Set these to an integer (e.g., 100) to limit dataset size for rapid testing
    MAX_TRAIN_SAMPLES = None
    MAX_VAL_SAMPLES = None
